def _sha256_file(path) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for block in iter(lambda: handle.read(1 << 20), b""):
            digest.update(block)
    return digest.hexdigest()

def load_verified_json(path, sha256):
    raw = Path(path).read_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    if digest != sha256:
        raise SystemExit(f"{path}: sha256 {digest} is not {sha256}")
    return json.loads(raw)

def _leaves(obj, path: str, out: dict | None = None) -> dict:
    """``{path: value}`` for every leaf of ``obj``; tensors and arrays by digest."""
    import numpy as np
    import torch
    out = {} if out is None else out
    if isinstance(obj, torch.Tensor):
        flat = obj.detach().cpu().contiguous().reshape(-1)
        digest = hashlib.sha256(f'{obj.dtype}|{tuple(obj.shape)}|'.encode())
        digest.update(flat.view(torch.uint8).numpy().tobytes())
        out[path] = f'tensor:{digest.hexdigest()}'
    elif isinstance(obj, np.ndarray):
        array = np.ascontiguousarray(obj)
        digest = hashlib.sha256(f'{array.dtype}|{array.shape}|'.encode())
        digest.update(array.tobytes())
        out[path] = f'array:{digest.hexdigest()}'
    elif isinstance(obj, dict):
        for key in sorted(obj, key=repr):
            _leaves(obj[key], f'{path}/{key}', out)
    elif isinstance(obj, (list, tuple)):
        for index, value in enumerate(obj):
            _leaves(value, f'{path}[{index}]', out)
    elif isinstance(obj, float):
        out[path] = f'float:{obj.hex()}'
    elif isinstance(obj, (bytes, bytearray)):
        try:
            inner = pickle.loads(obj)
        except Exception:  # not a pickle: compare the bytes
            out[path] = f'bytes:{hashlib.sha256(obj).hexdigest()}'
        else:
            _leaves(inner, f'{path}<pickle>', out)
    else:
        text = repr(obj)
        out[path] = text if len(text) <= 160 else (
            f'{type(obj).__name__}:{hashlib.sha256(text.encode()).hexdigest()}')
    return out

def _renders(args, root: Path):
    """Write the render files once; the same bytes serve every arm."""
    import torch

    root.mkdir(parents=True, exist_ok=True)
    generator = torch.Generator().manual_seed(1192)
    manifest = {}
    for unit in range(args.units):
        name = f"unit{unit:02d}"
        source = (torch.rand((args.dim, args.dim), generator=generator) * 2 - 1) / args.dim ** 0.5
        torch.save(source.to(torch.bfloat16), root / f"{name}.source.pt")
        for index, fmt in enumerate(FORMATS):
            path = root / f"{name}.{fmt}.pt"
            torch.save((source + (index + 1) / 128).to(torch.bfloat16), path)
            manifest[f"{name}|{fmt}"] = {
                "path": str(path), "sha256": hashlib.sha256(path.read_bytes()).hexdigest()}
    (root / "manifest.json").write_text(json.dumps(manifest, indent=1, sort_keys=True))
    return manifest

def load_slice(path: str, sha256: str) -> dict:
    raw = Path(path).read_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    if digest != sha256:
        raise SystemExit(f"slice digest {digest} is not --slice-sha256 {sha256}")
    return json.loads(raw)
